pub unsafe fn draw_prediction_line(mut golfBall: Gc<terraria::entity::Entity>, mut impactVelocity: terraria_core::xna::Vector2, mut chargeProgress: f32, mut roughLandResistance: f32) {
    if (*terraria::game_content::golf::golf_helper::s()).prediction_line.is_null()
    {
        (*terraria::game_content::golf::golf_helper::s()).prediction_line = rt::wbv(terraria::game_content::golf::fancy_golf_prediction_line::new(20));
    }
    terraria::game_content::golf::fancy_golf_prediction_line::update((*terraria::game_content::golf::golf_helper::s()).prediction_line.ptr(), golfBall, impactVelocity, roughLandResistance);
    terraria::game_content::golf::fancy_golf_prediction_line::draw((*terraria::game_content::golf::golf_helper::s()).prediction_line.ptr(), (*terraria::main::s()).camera, (*terraria::main::s()).sprite_batch, chargeProgress);
}

